import {apiFetch} from '@/aitech/api';
'use client';
import {useEffect,useMemo,useRef,useState} from 'react';
import {ArrowLeft,ArrowUpRight,Soup,Clock,Info,MapPin,Phone,RefreshCw,Search,ChevronDown} from 'lucide-react';
import {Select,SelectContent,SelectItem,SelectTrigger,SelectValue} from '@/components/ui/select';
import {Switch} from '@/components/ui/switch';
import {Empty,EmptyDescription,EmptyHeader,EmptyTitle} from '@/components/ui/empty';
import {checkedOn,holidaySource,holidays,holidayYears,ramenShops,regions} from '@/lib/ramen-data';
import {addDays,clockText,hoursText,japanDate,shopStatus,type RamenShop,type ShopStatus} from '@/lib/ramen-hours';
import s from './ramen.module.css';

const labels={open:'営業中（時間上）','last-order':'ラストオーダー終了',closed:'営業時間外',unknown:'要確認'};
const weekdays=['日','月','火','水','木','金','土'];
const dateFormatter=new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'long',day:'numeric',weekday:'short'});
const timeFormatter=new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
const normalize=(value:string)=>value.normalize('NFKC').toLocaleLowerCase('ja').replace(/\s+/g,'');
const dayLabel=(key:string,today:string)=>key===today?'今日':key===addDays(today,1)?'明日':`${Number(key.slice(5,7))}/${Number(key.slice(8,10))}`;

function ShopCard({shop,status,today}:{shop:RamenShop;status:ShopStatus;today:string}) {
  const map='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(shop.name+' '+shop.address);
  const soon=status.state==='open'&&(status.minutesLeft??999)<=30;
  const calendarException=shop.exceptions&&Object.hasOwn(shop.exceptions,today);
  return <article className={`${s.card} ${status.state==='open'?s.cardOpen:''}`}>
    <div className={s.cardTop}><span className={s.city}><MapPin size={14}/>{shop.city}</span><span className={`${s.badge} ${s[status.state.replace('-','')]}`}>{labels[status.state]}</span></div>
    <h2>{shop.name}</h2>
    <p className={s.kind}>{shop.kind}</p>
    <div className={s.hours}>
      <Clock size={18}/><div><span className={s.hoursLabel}>{status.businessDate&&status.businessDate!==today?'前日からの営業':'今日の営業時間'}</span>
        <strong>{status.businessDate&&status.businessDate!==today&&status.active?hoursText([status.active]):hoursText(status.today)}</strong>
        {status.active?.lastOrder!==undefined?<span>ラストオーダー {clockText(status.active.lastOrder)}</span>:status.active?<span>ラストオーダーの記載なし</span>:null}
      </div>
    </div>
    {soon&&<p className={s.soon}>{status.active?.lastOrder===undefined?'閉店':'ラストオーダー'}まで約{status.minutesLeft}分</p>}
    {status.state==='closed'&&status.next&&<p className={s.next}>{dayLabel(status.next.date,today)} {clockText(status.next.open)} 開店予定</p>}
    {status.state==='closed'&&calendarException&&<p className={s.soon}>公表された休業日です</p>}
    {status.state==='unknown'&&<p className={s.soon}>{status.reason}。公式情報をご確認ください。</p>}
    {status.state==='last-order'&&<p className={s.soon}>新規注文の受付時間を過ぎています</p>}
    <p className={s.address}>{shop.address.replace(/^岐阜県/,'')}</p>
    <div className={s.actions}><a className={s.mapButton} href={map} target="_blank" rel="noopener noreferrer"><MapPin size={17}/>地図で見る<ArrowUpRight size={16}/></a>{shop.phone&&<a className={s.phoneButton} href={'tel:'+shop.phone.replaceAll('-','')} aria-label={shop.name+'に電話する'}><Phone size={17}/>電話</a>}</div>
    <details className={s.details}>
      <summary>定休日・週間営業時間<ChevronDown size={16}/></summary>
      <p>{shop.closedLabel}</p>
      <dl className={s.week}>{shop.week.map((hours,i)=><div key={i}><dt>{weekdays[i]}</dt><dd>{hoursText(hours)}{hours?.some(h=>h.lastOrder!==undefined)&&<small>{hours.filter(h=>h.lastOrder!==undefined).map(h=>'L.O. '+clockText(h.lastOrder!)).join(' / ')}</small>}</dd></div>)}</dl>
      {shop.holiday!==undefined&&<p>祝日：{hoursText(shop.holiday)}</p>}
      {shop.holidayEve!==undefined&&<p>祝日前（営業日のみ）：{hoursText(shop.holidayEve)}</p>}
      {shop.note&&<p>{shop.note}</p>}
      <p className={s.checked}>営業時間の確認：{shop.checkedOn.replaceAll('-','/')}</p>
    </details>
    <a className={s.source} href={shop.source} target="_blank" rel="noopener noreferrer">{shop.sourceLabel}<ArrowUpRight size={14}/></a>
  </article>;
}

export default function RamenDirectory({initialNow}:{initialNow:number}) {
  const [now,setNow]=useState(initialNow),[ready,setReady]=useState(false);
  const [query,setQuery]=useState(''),[area,setArea]=useState('all'),[openOnly,setOpenOnly]=useState(true);
  const [syncing,setSyncing]=useState(false),[clockError,setClockError]=useState(false);
  const offset=useRef<number|null>(null),pending=useRef(false);
  async function syncClock(){
    if(pending.current)return;
    pending.current=true;setSyncing(true);
    try {
      const start=Date.now();
      const response=await apiFetch('/api/ramen/time',{cache:'no-store',signal:AbortSignal.timeout(8000)});
      if(!response.ok)throw new Error('time');
      const data=await response.json();
      if(!data||typeof data!=='object'||!('now' in data)||typeof data.now!=='number'||!Number.isFinite(data.now))throw new Error('time');
      const end=Date.now();offset.current=data.now-(start+end)/2;
      setNow(end+offset.current);setClockError(false);
    } catch {setNow(Date.now()+(offset.current??0));setClockError(true);}
    finally {pending.current=false;setSyncing(false);setReady(true);}
  }
  useEffect(()=>{
    setNow(Date.now());setReady(true);void syncClock();
    const timer=window.setInterval(()=>{if(!document.hidden)setNow(Date.now()+(offset.current??0));},1000);
    const resync=window.setInterval(()=>{if(!document.hidden)void syncClock();},300000);
    const onVisible=()=>{if(!document.hidden){setNow(Date.now()+(offset.current??0));void syncClock();}};
    document.addEventListener('visibilitychange',onVisible);window.addEventListener('pageshow',onVisible);
    return()=>{window.clearInterval(timer);window.clearInterval(resync);document.removeEventListener('visibilitychange',onVisible);window.removeEventListener('pageshow',onVisible);};
  },[]);
  const minute=Math.floor(now/60000);
  const entries=useMemo(()=>ramenShops.map(shop=>({shop,status:shopStatus(shop,minute*60000,holidays,holidayYears)})),[minute]);
  const selected=entries.filter(({shop})=>(area==='all'||shop.region===area||shop.city===area)&&normalize([shop.name,shop.city,shop.address,shop.kind].join(' ')).includes(normalize(query)));
  const openCount=selected.filter(({status})=>status.state==='open').length;
  const visible=selected.filter(({status})=>!openOnly||status.state==='open').sort((a,b)=>{
    const order={open:0,'last-order':1,closed:2,unknown:3};
    return order[a.status.state]-order[b.status.state] || regions.indexOf(a.shop.region)-regions.indexOf(b.shop.region) || a.shop.city.localeCompare(b.shop.city,'ja') || a.shop.name.localeCompare(b.shop.name,'ja');
  });
  const {key:today}=japanDate(now);
  const stale=(now-Date.parse(checkedOn+'T00:00:00+09:00'))>90*86400000;
  function clear(){setQuery('');setArea('all');}

  return <div className={s.page}>
    <a className="skip-link" href="#ramen-results">店舗一覧へ移動</a>
    <header className={s.nav}><a href="/commons/" className={s.back}><ArrowLeft size={17}/>COMMONS</a><span><Soup size={19}/>岐阜のラーメン</span></header>
    <main className={s.main}>
      <section className={s.heading} aria-labelledby="ramen-title">
        <div><p className={s.eyebrow}>岐阜県内 · {ramenShops.length}店舗掲載</p><h1 id="ramen-title">いま、開いている<br className={s.mobileBreak}/>ラーメン店。</h1><p className={s.lead}>公表営業時間を、日本時間で自動判定。</p></div>
        <figure className={s.photo}><img src="data:image/jpeg;base64," alt="ラーメンのイメージ写真" width="800" height="600"/><figcaption>イメージ写真</figcaption></figure>
      </section>

      <section className={s.filterPanel} aria-label="店舗の絞り込み">
        <div className={s.livebar}><div className={s.liveClock}><Clock size={19}/><span>{ready?dateFormatter.format(now):'日本時間を確認中'}</span><time dateTime={new Date(now).toISOString()}>{timeFormatter.format(now)}</time><span className={s.jst}>日本時間</span></div><button className={s.refresh} onClick={()=>void syncClock()} disabled={syncing}><RefreshCw size={16} className={syncing?s.spin:''}/><span>{syncing?'確認中':'時刻を更新'}</span></button></div>
        <div className={s.controls}>
          <div className={s.search}><Search size={19}/><input aria-label="店名・市町村を検索" placeholder="店名・市町村で検索" value={query} onChange={e=>setQuery(e.target.value)}/></div>
          <Select value={area} onValueChange={setArea}><SelectTrigger className={s.select} aria-label="エリアを選択"><MapPin size={17}/><SelectValue/></SelectTrigger><SelectContent position="popper"><SelectItem value="all">岐阜県すべて</SelectItem>{regions.map(region=><SelectItem key={region} value={region}>{region}エリア</SelectItem>)}{[...new Set(ramenShops.map(shop=>shop.city))].sort((a,b)=>a.localeCompare(b,'ja')).map(city=><SelectItem key={city} value={city}>{city}</SelectItem>)}</SelectContent></Select>
          <label className={s.toggle}><Switch checked={openOnly} onCheckedChange={setOpenOnly} aria-label="営業中のみ表示"/>営業中のみ</label>
        </div>
        <div className={s.explanation}><Info size={17}/><p><strong>通常営業時間からの目安です。</strong>臨時休業・売り切れ・当日の変更は反映しきれません。来店前に公式情報や電話でご確認ください。</p></div>
        {clockError&&<p className={s.warning} role="status">時刻を再取得できませんでした。{offset.current===null?'端末の時計':'前回取得した時刻'}を使って判定しています。</p>}
        {stale&&<p className={s.warning} role="status">営業時間の確認から90日以上経過しています。現在の営業時間は各店の公式情報をご確認ください。</p>}
      </section>

      <div className={s.resultHeader}><h2>{openOnly?'営業中の店舗':'掲載店舗'}<span>{visible.length}<small>件</small></span></h2><p role="status">{area==='all'?'岐阜県':area} · {openCount}件が営業時間内</p></div>
      {(query||area!=='all')&&<div className={s.filterSummary}><span>{area!=='all'?area+' / ':''}{query?`「${query}」`:''}</span><button onClick={clear}>絞り込みを解除</button></div>}
      <section id="ramen-results" className={s.grid} aria-label="ラーメン店一覧" tabIndex={-1}>
        {visible.map(({shop,status})=><ShopCard key={shop.id} shop={shop} status={status} today={today}/>)}
      </section>
      {!visible.length&&<Empty className={s.empty}><EmptyHeader><Soup size={36}/><EmptyTitle>{openOnly?'条件に合う営業中の店はありません':'条件に合う掲載店はありません'}</EmptyTitle><EmptyDescription>{openOnly?'掲載店舗の通常営業時間による結果です。条件を広げるか、営業時間外の店舗も確認できます。':'エリアや検索する言葉を変えてお試しください。'}</EmptyDescription></EmptyHeader><div className={s.emptyActions}>{openOnly&&<button className={s.mapButton} onClick={()=>setOpenOnly(false)}>営業時間外も表示</button>}{(query||area!=='all')&&<button className={s.phoneButton} onClick={clear}>絞り込みを解除</button>}</div></Empty>}

      <footer className={s.footer}>
        <p>営業時間の確認：{checkedOn.replaceAll('-','/')} · 営業判定は1分ごとに更新</p>
        <p>営業時間を確認できた{ramenShops.length}店舗を掲載しています。岐阜県内すべての店を網羅する一覧ではありません。営業時間データの自動収集は行っていません。</p>
        <p>「営業中のみ」では、掲載されたラストオーダーを過ぎた店を除外します。ラストオーダーの記載がない店は閉店時刻で判定します。</p>
        <details><summary>情報の出典・判定について</summary><p>各店舗のリンク先に掲載された通常営業時間・定休日を使用しています。確認できた日付指定の休業を優先し、昼夜の休憩・前日からの深夜営業・祝日による振替に対応しています。年末年始やお盆などの特別営業、並び列の受付終了は通常と異なる場合があります。</p><p><a href={holidaySource} target="_blank" rel="noopener noreferrer">祝日：内閣府「国民の祝日」</a>。未確認の年別営業カレンダーは「要確認」と表示します。</p></details>
        <p className={s.credit}>写真：<a href="https://commons.wikimedia.org/wiki/File:Ramen_(3233422299).jpg" target="_blank" rel="noopener noreferrer">David Pursehouse / Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by/2.0/" target="_blank" rel="noopener noreferrer">CC BY 2.0</a>（トリミング・イメージ写真）</p>
        <a className={s.footerBack} href="/commons/"><ArrowLeft size={16}/>COMMONSのサイト一覧へ</a>
      </footer>
    </main>
  </div>;
}
